-- Lo que ya estaba guardado toma el de su municipio (no pisa uno escrito a mano).
UPDATE sst.terceros t SET codigo_postal = m.codigo_postal
  FROM sst.municipios m WHERE m.id = t.municipio_id AND t.codigo_postal IS NULL AND m.codigo_postal IS NOT NULL;
UPDATE sst.emisor e SET codigo_postal = m.codigo_postal
  FROM sst.municipios m WHERE m.id = e.municipio_id AND e.codigo_postal IS NULL AND m.codigo_postal IS NOT NULL;

COMMIT;
